private.reference_solution:
#include <iostream>
#include <string>

class Employee {
public:
    explicit Employee(int base) : base_(base) {}
    int salary() const { return base_; }
protected:
    int base_;
};

class Manager : public Employee {
public:
    Manager(int base, int bonus) : Employee(base), bonus_(bonus) {}
    int salary() const { return base_ + bonus_; }
private:
    int bonus_;
};

int main() {
    int base = 0;
    int bonus = 0;
    std::string role;
    std::cin >> base >> bonus >> role;
    if (role == "manager") {
        Manager lead(base, bonus);
        std::cout << lead.salary() << std::endl;
    } else {
        Employee staff(base);
        std::cout << staff.salary() << std::endl;
    }
    return 0;
}
